/* Congregación El Calafate · Visual System 2026 · V1.7.0 */
(()=>{
'use strict';
const VERSION='1.7.0';
const STATE_KEY='cec_territory_official_v150';
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||'')||f}catch(_){return f}};
function icon(name){const c='viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"';const p={home:'<path d="M3.5 10.8 12 3.8l8.5 7v9.4H14v-5.7h-4v5.7H3.5z"/>',calendar:'<rect x="3.5" y="5" width="17" height="15" rx="2.5"/><path d="M7 3v4M17 3v4M3.5 9h17M8 13h2M14 13h2M8 16.5h2M14 16.5h2"/>',pin:'<path d="M12 21s6-5.1 6-11a6 6 0 1 0-12 0c0 5.9 6 11 6 11Z"/><circle cx="12" cy="10" r="2.2"/>',docs:'<path d="M7 3.5h7l4 4v13H7z"/><path d="M14 3.5v4h4M10 12h5M10 15.5h5"/>',users:'<path d="M8.4 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM3 19c.4-3.2 2.2-5 5.4-5s5 1.8 5.4 5M16.6 10.5a2.5 2.5 0 1 0 0-5M15.4 14c3.2 0 5 1.5 5.6 4.5"/>',more:'<circle cx="5" cy="12" r="1.2" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1.2" fill="currentColor" stroke="none"/><circle cx="19" cy="12" r="1.2" fill="currentColor" stroke="none"/>',shield:'<path d="M12 3 19 6v5.1c0 4.4-2.6 7.7-7 9.9-4.4-2.2-7-5.5-7-9.9V6z"/><path d="m9 12 2 2 4-4"/>',back:'<path d="m14.5 6-6 6 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6.1 8.5A7 7 0 0 1 18.7 7M17.9 15.5A7 7 0 0 1 5.3 17"/>',move:'<path d="M12 2v20M2 12h20M12 2l-2.5 2.5M12 2l2.5 2.5M12 22l-2.5-2.5M12 22l2.5-2.5M2 12l2.5-2.5M2 12l2.5 2.5M22 12l-2.5-2.5M22 12l-2.5 2.5"/>',map:'<path d="m4 5 5-2 6 2 5-2v16l-5 2-6-2-5 2zM9 3v16M15 5v16"/>',file:'<path d="M7 3.5h7l4 4v13H7z"/><path d="M14 3.5v4h4"/>'};return `<svg ${c}>${p[name]||p.file}</svg>`}
function addStyles(){if($('#p170Styles'))return;const l=document.createElement('link');l.id='p170Styles';l.rel='stylesheet';l.href='premium-v170.css';document.head.appendChild(l)}
function greeting(){const h=new Date().getHours();return h<12?'Buenos días':h<20?'Buenas tardes':'Buenas noches'}
function navigateByButton(target){const b=$(`.nav-item[data-target="${target}"]`);if(b)b.click();else{$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===target));window.scrollTo({top:0,behavior:'smooth'})}}
function upgradeHome(){const home=$('#inicio'),hero=$('#inicio .hero');if(!home||!hero)return;if(!hero.querySelector('.p170-hero-photo'))hero.innerHTML='<img class="p170-hero-photo" src="congregacion-home.jpg" alt="Congregación El Calafate"><div class="p170-hero-grid"></div><div class="p170-hero-wash"></div><div class="p170-hero-tech"></div><div class="p170-hero-top"><div class="p170-hero-brand">CONGREGACIÓN<br>EL CALAFATE</div><div class="p170-hero-coord">50.339° S<br>72.276° O</div></div>';if(!$('.p170-greeting',home)){const g=document.createElement('section');g.className='p170-greeting';g.innerHTML=`<p class="p170-kicker">CONGREGACIÓN EL CALAFATE</p><h1><span id="p170Greeting">${greeting()}</span><i></i></h1><p>Todo lo importante para hoy, en un solo lugar.</p><button type="button" class="p170-system-card" data-p170-system><span class="p170-system-dot"></span><strong>Sistema actualizado · Octubre 2026</strong><span>›</span></button>`;hero.insertAdjacentElement('afterend',g)}else $('#p170Greeting').textContent=greeting();const q=$('#quickGrid');if(q&&!q.querySelector('[data-p170-quick]')){const items=[['reuniones','Reuniones','Programas y calendario','calendar'],['territorios','Territorios','Mapa y progreso','pin'],['carritos','Carritos','Turnos y vacantes','users'],['recursos','Recursos','Documentos y formularios','docs']];q.innerHTML=items.map((x,i)=>`<button type="button" class="quick-card" data-p170-quick="${x[0]}"><span class="p170-q-no">0${i+1}</span><span class="quick-card-icon">${icon(x[3])}</span><span><strong>${x[1]}</strong><small>${x[2]}</small></span><span class="p170-q-arrow">${icon('chevron')}</span></button>`).join('')}const qs=q?.closest('.section-block');if(qs){const k=$('.section-kicker',qs),h=$('h2',qs);if(k)k.textContent='';if(h)h.textContent='Accesos rápidos';const row=$('.section-title-row',qs);if(row&&!$('.p170-section-index',row)){const s=document.createElement('span');s.className='p170-section-index';s.textContent='// 04';row.appendChild(s)}}const news=$('.news-list',home);if(news){const sec=news.closest('.section-block'),k=$('.section-kicker',sec),h=$('h2',sec),pill=$('.pill',sec);if(k)k.textContent='';if(h)h.textContent='Actividad reciente';if(pill)pill.textContent='// 04'}const em=$('.emergency-card',home),ei=$('.emergency-icon',em);if(ei)ei.innerHTML=icon('shield')}
function bindPremiumActions(){if(document.body.dataset.p170Bound)return;document.body.dataset.p170Bound='1';document.addEventListener('click',e=>{const q=e.target.closest?.('[data-p170-quick]');if(q){const a=q.dataset.p170Quick;if(a==='carritos')window.CongElCalafateCarritos?.open?.('carrito-anonima');else navigateByButton(a);return}if(e.target.closest?.('[data-p170-system]'))navigateByButton('recursos')})}
function activeView(){return $('.view.active')?.dataset?.view||'inicio'}function syncView(){document.body.dataset.p170View=activeView()}
function upgradeHeaders(){const cfg={reuniones:['Reuniones','Programas, calendario y organización','calendar'],territorios:['Territorios','Estado de predicación','pin'],recursos:['Recursos','Documentos y herramientas','docs'],mas:['Más','Otros accesos y ajustes','more']};Object.entries(cfg).forEach(([id,[t,s,ic]])=>{const h=$('.page-head',$('#'+id));if(!h)return;const h1=$('h1',h),p=$('p:not(.section-kicker)',h),i=$('.page-icon',h);if(h1)h1.textContent=t;if(p)p.textContent=s;if(i&&!i.dataset.p170){i.dataset.p170='1';i.innerHTML=icon(ic)}})}
function upgradeNav(){const map={inicio:'home',reuniones:'calendar',territorios:'pin',recursos:'docs',mas:'more'};$$('.nav-item').forEach(b=>{const s=$('span',b),n=map[b.dataset.target];if(s&&n&&!s.dataset.p170){s.dataset.p170='1';s.innerHTML=icon(n)}})}
function upgradeResourceIcons(){$$('.resource-card').forEach(c=>{const i=$('.resource-icon',c);if(!i||i.dataset.p170)return;i.dataset.p170='1';const t=(c.textContent||'').toLowerCase();let n='file';if(/calend|reuni|programa/.test(t))n='calendar';else if(/territ|mapa/.test(t))n='map';else if(/carrito/.test(t))n='users';else if(/seguridad|evacu/.test(t))n='shield';else if(/form|solicitud|document|carta|informe|planilla/.test(t))n='docs';i.innerHTML=icon(n)})}
function addMeetingFeature(){const v=$('#reuniones'),list=$('#meetingResources');if(!v||!list||$('.p170-meeting-feature',v))return;const b=document.createElement('button');b.type='button';b.className='p170-meeting-feature';b.dataset.resource='calendario';b.innerHTML=`<span class="p170-meeting-date">${icon('calendar')}</span><span class="p170-meeting-copy"><small>Próxima reunión</small><strong>Calendario y programa actual</strong><span>Consultar horario, programa y próximos eventos</span></span><span class="p170-meeting-arrow">${icon('chevron')}</span>`;list.parentNode.insertBefore(b,list)}
function territoryMetric(n){const DATA=window.CongTerritoryOfficialData?.data||{},d=DATA[String(n)];if(!d)return{done:0,total:0,pct:0};const state=read(STATE_KEY,{}),done=state[String(n)]?.done||{};let keys=[];if(d.type==='tramos')keys=(d.items||[]).map(x=>x+'::territorio');else(d.items||[]).forEach(x=>['N','E','S','O'].forEach(s=>keys.push(x+'::'+s)));const c=keys.filter(k=>!!done[k]).length;return{done:c,total:keys.length,pct:keys.length?Math.round(c*100/keys.length):0}}
function territoryStats(){let complete=0,progress=0,pending=0;for(let n=1;n<=102;n++){const m=territoryMetric(n);if(m.total&&m.done>=m.total)complete++;else if(m.done>0)progress++;else pending++}return{complete,progress,pending,total:102}}
function addTerritoryOverview(){const v=$('#territorios'),head=$('.page-head',v);if(!v||!head)return;let o=$('.p170-territory-overview',v);if(!o){o=document.createElement('section');o.className='p170-territory-overview';head.insertAdjacentElement('afterend',o)}const s=territoryStats();o.innerHTML=`<div class="p170-tstat primary"><strong>${s.total}</strong><span>territorios</span></div><div class="p170-tstat done"><strong>${s.complete}</strong><span>completados</span></div><div class="p170-tstat progress"><strong>${s.progress}</strong><span>en progreso</span></div><div class="p170-tstat"><strong>${s.pending}</strong><span>pendientes</span></div>`}
function territoryStatus(n){const m=territoryMetric(n);return m.total&&m.done>=m.total?'done':m.done>0?'progress':'pending'}
function installTerritoryFilters(){const wrap=$('.cec-territory-grid-wrap'),grid=$('#cecTerritoryGrid');if(!wrap||!grid)return;let f=$('.p170-territory-filter',wrap);if(!f){f=document.createElement('div');f.className='p170-territory-filter';f.dataset.filter='all';f.innerHTML='<button class="active" data-p170-tfilter="all">Todos</button><button data-p170-tfilter="pending">Pendientes</button><button data-p170-tfilter="progress">En progreso</button><button data-p170-tfilter="done">Completados</button>';$('.cec-territory-grid-head',wrap)?.insertAdjacentElement('afterend',f);f.addEventListener('click',e=>{const b=e.target.closest('[data-p170-tfilter]');if(!b)return;f.dataset.filter=b.dataset.p170Tfilter;$$('button',f).forEach(x=>x.classList.toggle('active',x===b));applyTerritoryFilter()})}applyTerritoryFilter()}
function applyTerritoryFilter(){const f=$('.p170-territory-filter'),grid=$('#cecTerritoryGrid');if(!f||!grid)return;const mode=f.dataset.filter||'all';$$('[data-n]',grid).forEach(b=>{b.hidden=mode!=='all'&&territoryStatus(b.dataset.n)!==mode})}
function enhanceMapTouch(){const vp=$('#cecV162Viewport'),head=$('.cec-v162-head'),svg=$('#cecV162Svg');if(!vp||!head)return;let pan=$('#p170MapPan');if(!pan){pan=document.createElement('button');pan.id='p170MapPan';pan.type='button';pan.className='p170-map-pan';pan.innerHTML=`${icon('move')}<span>Mover</span>`;head.insertBefore(pan,$('#cecV162Fit')||null);pan.onclick=()=>{vp.classList.toggle('p170-pan-mode');pan.classList.toggle('active',vp.classList.contains('p170-pan-mode'));if(!vp.classList.contains('p170-pan-mode'))$('#cecV162Fit')?.click()}}if(!vp.dataset.p170Touch){vp.dataset.p170Touch='1';$('#cecV162Plus')?.addEventListener('click',()=>{vp.classList.add('p170-pan-mode');pan?.classList.add('active')},true);$('#cecV162Minus')?.addEventListener('click',()=>{vp.classList.add('p170-pan-mode');pan?.classList.add('active')},true);$('#cecV162Fit')?.addEventListener('click',()=>{vp.classList.remove('p170-pan-mode');pan?.classList.remove('active')},true)}const drawing=!!svg?.classList.contains('drawing');vp.classList.toggle('p170-drawing',drawing);if(drawing){vp.classList.remove('p170-pan-mode');pan?.classList.remove('active')}}
function premiumCarritos(){const s=$('#cecCarritosScreen');if(!s)return;const t=$('.cec-c-head-title strong',s),sm=$('.cec-c-head-title small',s);if(t)t.textContent='Carritos';if(sm)sm.textContent='TURNOS Y VACANTES';const back=$('.cec-c-back',s),ref=$('.cec-c-refresh',s);if(back&&!back.dataset.p170){back.dataset.p170='1';back.innerHTML=icon('back')}if(ref&&!ref.dataset.p170){ref.dataset.p170='1';ref.innerHTML=icon('refresh');ref.setAttribute('aria-label','Actualizar')}$$('.cec-v141-icon',s).forEach(i=>{if(!i.dataset.p170){i.dataset.p170='1';i.innerHTML=icon('users')}})}
function patchAbout(){const s=$('.about-card strong'),p=$('.about-card p');if(s)s.textContent='Aplicación v1.7.0 · Visual System 2026';if(p)p.textContent='Nueva identidad visual premium aplicada a Inicio, Reuniones, Territorios, mapas, Carritos, Recursos, modales y navegación. Se preservan las funciones y datos existentes.'}
function patchDiagnostic(){const ta=$('#cecDiagText');if(ta)ta.value=String(ta.value||'').replace(/Versión módulo diagnóstico: .*$/m,'Versión módulo diagnóstico: 1.7.0 · Visual System 2026').replace(/Versión app: 1\.6\.4/g,'Versión app: 1.7.0').replace(/VersionCode: 22/g,'VersionCode: 24');const sum=$('#cecDiagSummary');if(sum){const chip=$$('.cec-diag-chip',sum).find(x=>/^App\s/.test(x.textContent||''));if(chip)chip.textContent='App 1.7.0'}}
let timer=0;function refresh(){addStyles();document.body.classList.add('p170');syncView();upgradeHome();upgradeHeaders();upgradeNav();upgradeResourceIcons();addMeetingFeature();addTerritoryOverview();installTerritoryFilters();enhanceMapTouch();premiumCarritos();patchAbout();if($('#cecDiagOverlay')?.classList.contains('open'))setTimeout(patchDiagnostic,150)}function schedule(){clearTimeout(timer);timer=setTimeout(refresh,40)}
function observe(){const mo=new MutationObserver(schedule);mo.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class','style','hidden']});document.addEventListener('click',()=>setTimeout(()=>{addTerritoryOverview();applyTerritoryFilter();enhanceMapTouch()},100),true)}
addStyles();bindPremiumActions();if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{refresh();observe()},{once:true});else{refresh();observe()}setInterval(()=>{const g=$('#p170Greeting');if(g)g.textContent=greeting();if(activeView()==='territorios')addTerritoryOverview()},60000);window.CongElCalafateVisualV170={version:VERSION,refresh,metric:territoryMetric};
})();
